mapper.select:
SELECT b.bno, b.btype, b.bwriter, b.btitle, b.bcontent, b.bimage, b.bview, b.bstatus, b.bcreate, b.bupdate, b.mno,
m.mname AS realWriterName, m.memail AS realWriterEmail
FROM board b LEFT JOIN member m ON b.mno = m.mno WHERE b.bno = #{bno}

mapper.update:
UPDATE board
SET bview = NVL(bview, 0) + 1
WHERE bno = #{bno}
